node.interaction_0_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	Game_SaveGame();
	Actor_QueueActionSetSolid(so_activator, false);
	Actor_QueueActionMoveToDistanceFromActor(so_activator, so_self, 58);
	Actor_QueueActionSetSolid(so_activator, true);
	local pos = StageObject_GetStagePosition(so_self);
	Actor_QueueActionTurnTowardsPosition(so_activator, pos[0], pos[1]);
	Actor_QueueActionPlayAnimation(so_activator, "tool_unequip", true);
	local command = Command_Create("activate");
	Command_SetStageObjectReference(command, so_self);
	Actor_QueueActionSendCommand(so_activator, so_activator, command, 1.2);
	Command_Delete(command);
	Actor_QueueActionPlayAnimation(so_activator, "lighting_a_fire", true);
	Actor_QueueActionPlayAnimation(so_activator, "tool_equip", false);


	if (StageObject_GetId(so_self) == "underworld_start_campfire")
	{

		Game_AddActorNotificationWithDelay(so_activator, LOC_TEXT("The flame looks different. Pretty colors. [EMOJI=fire]"), 4)

	}

}

node.interaction_1_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	local wait_script = @"
	function IsWaiting()
	{
		return Game_IsStoringMaterials();
	}
	";

	Actor_SetActorFlag(so_activator, "INDESTRUCTIBLE", true);
	KeyValueStore_SetKeyValueBoolean(Engine_GetKeyValueStore(), "cinema_mode", true);
	local pos = StageObject_GetPosition(so_self);
	local so_storage_box = Stage_QueryNearestActorWithType(pos[0], pos[1], pos[2], 300, "actors/interactives/camp-storage-box.xml");

	// We may already be storing stuff.
	local engine_kvs = Engine_GetKeyValueStore();
	local storing_enabled = KeyValueStore_GetKeyValue(engine_kvs, "store_materials_when_resting") == true;
	if (storing_enabled && so_storage_box != null && !Game_IsStoringMaterials())
		Actor_InteractWithInteraction(so_storage_box, so_activator, "store");

	Actor_QueueActionTurnTowardsPosition(so_activator, pos[0], pos[1]);
	Actor_QueueActionPlayAnimation(so_activator, "tool_unequip", true);
	Actor_QueueActionPlayAnimationWithTransition(so_activator, "sitting_on_ground", "sitting_down", true);

	// Need to wait the previous storing and then start a new one in case we sat down while storing,
	// but picked up some materials between.
	Actor_QueueActionWaitForScript(so_activator, wait_script);
	if (storing_enabled && so_storage_box != null)
		Actor_InteractWithInteraction(so_storage_box, so_activator, "store");
	Actor_QueueActionWaitForScript(so_activator, wait_script);

	UI_SendScreenMessage("Campfire", "CampfireActor", so_self.tostring());
	UI_SendScreenMessage("Campfire", "PlayerActor", so_activator.tostring());
	Actor_QueueActionRunScript(so_activator, @"UI_PushScreen(""Campfire"");");

	Actor_QueueActionWaitForCommandWord(so_activator, "wait");
	Actor_QueueActionStopAnimationWithTransition(so_activator, "sitting_on_ground", "sitting_up", true);
	Actor_QueueActionPlayAnimation(so_activator, "tool_equip", false);

	//Actor_InteractWithInteraction(so_self, so_activator, "rest_camera");
}

node.interaction_2_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	local so_camera = StageObject_GetById("cinema_camera");
	Stage_SetActiveCamera(so_camera);
	local kvs_camera_paths = ActorType_GetKeyValueStore(Actor_GetActorType(so_self));
	Camera_RemoveAllAnimationsFromQueue(so_camera);
	Camera_AddAnimationToQueueAllPaths(so_camera, kvs_camera_paths, so_self);
	Camera_SetStageCameraAfterAnimationQueueIsFinished(so_camera, Stage_GetBaseCamera());
	Camera_SetStageCameraAnimationQueueLooping(so_camera, true);
}

node.interaction_3_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	local so_camera = StageObject_GetById("cinema_camera");
	Camera_RemoveAllAnimationsFromQueue(so_camera);
	Stage_SetActiveCamera(Stage_GetBaseCamera());


	//initial fast travel quest
	local quest_id = "quests/campfire-fast-travel-intro.nut";

	if(!Game_IsQuestCurrent(quest_id) || !Game_IsQuestCompleted(quest_id))
		Game_ShowQuestStartDialog("quests/campfire-fast-travel-intro.nut", true);

	quest_id = "quests/dlc_1_main.nut";

	//dlc main quest
	if(Game_IsQuestCurrent(quest_id)){

		 if(Game_GetQuestPhaseId(quest_id) == "PHASE_BACK_TO_TOWN"){



			 if(Game_GetWorldState("DLC_1_MAIN_QUEST", "travel_remark") != null){

				 local remark3 = LOC_TEXT("My travel troubles continue. [EMOJI=frowning face]")

				 if(m_randf() >= 0.6)
					 Game_AddActorNotificationWithDelay(so_activator, remark3, 3)

				 return;
			 }


			 local remark1 = LOC_TEXT("Strange. I can't use the Campfires for traveling any more. [EMOJI=compass]");
			 local remark2 = LOC_TEXT("Those devices I broke must have been important. [EMOJI=grimacing face]");

			 Game_AddActorNotificationWithDelay(so_activator, remark1, 2);
			 Game_AddActorNotification(so_activator,remark2);

			 Game_SetWorldState("DLC_1_MAIN_QUEST", "travel_remark", "1");


		 }


	}





}

node.interaction_4_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	local script_end_start = @"
		Game_SetCinemaMode(true);
		";
//    StageObject_SetPositionByStackingOnTop(so_activator, )
	Actor_QueueActionRunScript(so_activator, script_end_start);
//    Actor_QueueActionPlayAnimation(so_activator, "tool_unequip", false);
	Game_SetCinemaMode(true, true);

	Actor_QueueActionRunScript(so_activator, format("StageObject_AddTag(%d, \"IGNORE_SMALL_COLLISIONS\");", so_activator));
	Actor_QueueActionMoveToDistanceFromActor(so_activator, so_self, 80);
	Actor_QueueActionRunScript(so_activator, format("StageObject_RemoveTag(%d, \"IGNORE_SMALL_COLLISIONS\");", so_activator));

//    Actor_QueueActionMoveToBone(so_activator, so_self, "snap");
//    Actor_QueueActionPlayAnimation(so_activator, "tool_equip", true);
	local script_end = @"
		Game_SetCinemaMode(false);
		";
	Actor_QueueActionRunScript(so_activator, script_end);
}

node.interaction_5_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
		local identifier = "puid_" + StageObject_GetPersistentUniqueId(so_self);
		local worldstate = Game_GetWorldState("UW_CAMPFIRES_FOUND",identifier);


		if(worldstate == null){


			local quest_id = "quests/campfire-fast-travel-intro.nut";

			if(Game_IsQuestCurrent(quest_id)){

				if(!Game_IsQuestGoalCompleted(quest_id, "PHASE_USE_FAST_TRAVEL", "GOAL_FIND_ANOTHER_CAMPFIRE")){

					Game_SendQuestPhaseGoalCommandWord(quest_id,"PHASE_USE_FAST_TRAVEL","GOAL_FIND_ANOTHER_CAMPFIRE", "complete");

				}

			}


		}

		Game_SetWorldState("UW_CAMPFIRES_FOUND",identifier,"found");




}
